class.description:
Lists what [method PCKPackageServer.extract] did with each selected file of a pack: written (in [member written], under a new name also in [member renamed]), skipped ([member skipped]) or left out because it can't be edited as a source ([member not_editable]). [member dropped_uids] lists UIDs that were already used by other files, and [member errors] the files that could not be read or written. The result is read-only.
[codeblocks]
[gdscript]
var result := PCKPackageServer.extract(PCKPackageServer.open("user://mod.pck"), "user://mods/mod")
for path in result.written:
    print("written: ", path)
for path in result.renamed:
    print(path, " was written as ", result.renamed[path])
if not result.is_ok():
    push_error(error_string(result.error))
[/gdscript]
[csharp]
PckExtractResult result = PckPackageServer.Extract(PckPackageServer.Open("user://mod.pck"), "user://mods/mod");
foreach (string path in result.Written)
{
    GD.Print("written: ", path);
}
foreach (var (path, target) in result.Renamed)
{
    GD.Print(path, " was written as ", target);
}
if (!result.IsOk())
{
    GD.PushError(OS.GetErrorString(result.Error));
}
[/csharp]
[/codeblocks]
